 const noticeFields:Field[]=[{key:'title',label:'公告標題',required:true,maxLength:100},{key:'body',label:'公告內容（限模擬內容）',type:'textarea',maxLength:2000},{key:'unit_id',label:'公告對象（選填）',type:'select',nullable:true,options:unitOptions},{key:'pinned',label:'置頂公告',type:'checkbox',value:false},{key:'due_at',label:'截止時間（臺北，選填）',type:'datetime-local',nullable:true}];
