 const visibleNotices=data.notices.filter(row=>(!unit||row.unit_id===null||row.unit_id===unit)&&`${row.title} ${row.body}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())&&(noticeState==='all'||(noticeState==='archived'?!!row.archived:!row.archived))).sort((a,b)=>Number(!b.archived&&b.pinned)-Number(!a.archived&&a.pinned)||Date.parse(b.updated_at)-Date.parse(a.updated_at));
 const editTime=(row:OfficeData['shifts'][number],attendance:boolean)=>start({title:attendance?'更正手動出勤':'編輯班次時段',action:attendance?'office.attendance.update':'office.shift.update',description:'所屬組織與假員工不變。填寫更正原因；原值、新值與原因會保留在紀錄中。',base:idField(row),fields:[...timeFields.map(field=>({...field,value:localInput(row[field.key as 'start_at'|'end_at'])})),{...breakField,value:row.break_minutes},{...noteField,value:row.note},reasonField]});
 const editReservation=(row:OfficeData['reservations'][number])=>start({title:'更改設備預約',action:'office.reservation.update',description:'設備與假員工保留原紀錄。新時段仍須避開其他有效預約，原值與更改原因會保留。',base:idField(row),fields:[...timeFields.map(field=>({...field,value:localInput(row[field.key as 'start_at'|'end_at'])})),{key:'purpose',label:'借用用途（選填）',type:'textarea',value:row.purpose,maxLength:1000},reasonField]});
 const guideSteps=[{id:'unit',label:'建立組織',detail:'至少一個使用中的門市或部門。',done:activeUnits.length>0,reason:'',run:()=>{chooseTab('units');addUnit()}},{id:'staff',label:'加入假員工',detail:'至少一位使用中假員工，對應使用中組織。',done:activeStaff.length>0,reason:organizationReason,run:()=>{chooseTab('staff');addStaff()}},{id:'shift',label:'排第一個班次',detail:'至少一筆未取消班次，開始這週的流程練習。',done:data.shifts.some(row=>row.status!=='cancelled'),reason:peopleReason,run:()=>{chooseTab('shifts');addTime(false)}}];
 const guideCompleted=guideSteps.filter(step=>step.done).length,demoEmpty=officeTabs.every(({id})=>data[id].length===0)&&data.changes.length===0;
 const startDemo=()=>start({title:'建立合成行政示範',action:'office.demo.create',description:'只在空白行政桌建立 1 個組織、2 位假員工、5 個班次、2 筆手動出勤、1 份請購草稿、1 件設備、1 筆借用及 2 則公告。全部是合成資料；既有客戶、商品、錢包與訂單保留。',fields:[{key:'preset',label:'合成示範類型',type:'select',required:true,value:'store',options:[{value:'store',label:'合成店家示範'},{value:'office',label:'合成辦公室示範'},{value:'factory',label:'合成工廠示範'}]},{key:'week_start',label:'示範週星期一（臺北）',type:'date',required:true,value:week}]});
 const viewRows={units:visibleUnits,staff:visibleStaff,shifts:visibleShifts,attendance:visibleAttendance,requests:visibleRequests,equipment:visibleEquipment,reservations:visibleReservations,notices:visibleNotices};
 const label=officeTabs.find(item=>item.id===tab)!.label;
 const statusScope=({units:unitState?officeStatus[unitState]:'全部狀態',staff:staffStatus?officeStatus[staffStatus]:'全部狀態',shifts:shiftStatus?officeStatus[shiftStatus]:'全部狀態',attendance:attendanceState==='all'?'有效與作廢':attendanceState==='voided'?'已作廢':'有效紀錄',requests:[requestType?requestNames[requestType as keyof typeof requestNames]:'全部類型',requestStatus?officeStatus[requestStatus]:'全部狀態'].join('／'),equipment:equipmentState==='available_now'?'目前可用':equipmentState?officeStatus[equipmentState]:'全部狀態',reservations:reservationStatus==='returned'?'已歸還':reservationStatus?officeStatus[reservationStatus]:'全部狀態',notices:noticeState==='all'?'發布中與封存':noticeState==='archived'?'已封存':'發布中'} as Record<OfficeTab,string>)[tab];
 const period=tab==='shifts'||tab==='attendance'?`${week} 至 ${addDays(week,6)}（依開始日歸週）`:'全部日期';
 const report=officeReport(tab,viewRows[tab],data);
 const reportSummary=tab==='shifts'?`目前篩選的有效班次 ${visibleShifts.filter(row=>row.status!=='cancelled').length} 筆，共 ${visibleShifts.filter(row=>row.status!=='cancelled').reduce((total,row)=>total+netMinutes(row),0)} 分鐘；另保留 ${visibleShifts.filter(row=>row.status==='cancelled').length} 筆取消紀錄。`:
 tab==='attendance'?`目前篩選的有效出勤 ${visibleAttendance.filter(row=>!row.voided).length} 筆，共 ${visibleAttendance.filter(row=>!row.voided).reduce((total,row)=>total+netMinutes(row),0)} 分鐘；另保留 ${visibleAttendance.filter(row=>row.voided).length} 筆作廢紀錄，作廢不計入。`:
 tab==='requests'?`目前篩選的申請登錄合計 ${formatSIM(visibleRequests.reduce((total,row)=>total+row.amount_minor,0))}。此為模擬登錄金額，不代表核准或支付。`:
 tab==='notices'?`目前篩選 ${visibleNotices.filter(row=>!row.archived).length} 則發布中公告、${visibleNotices.filter(row=>row.archived).length} 則封存公告。封存公告不列入最近截止與置頂。`:`目前篩選共 ${viewRows[tab].length} 筆模擬紀錄。`;
 const reportScope=[['模式','SIM 流程練習'],['工作區',workspace.company_name],['工作區版本',String(workspace.version)],['資料類型',label],['組織範圍',unit?unitName(unit):'全部組織'],['搜尋條件',query||'未設定'],['狀態篩選',statusScope],['日期範圍',period],['時區','Asia/Taipei（UTC+08:00）'],['產出時間',formatDateTime(new Date().toISOString())],['篩選統計',reportSummary],['資料來源','目前訪客工作區的模擬紀錄；僅匯出目前篩選結果']];
 const exportCSV=()=>{const content=officeCSV([[...reportScope.map(item=>item[0]),...report.headers],...report.rows.map(row=>[...reportScope.map(item=>item[1]),...row])]);const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=officeFilename(tab);anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setMessage(`已匯出「${label}」目前篩選的 ${report.rows.length} 筆 SIM 紀錄。`)};
 const empty=(text:string)=><p className="office-empty">{query||unit||data[tab].length?'目前篩選、日期與狀態沒有符合的紀錄。可清除篩選、查看其他週，或切換紀錄狀態。':text}</p>;
